sys_variable_value.value:
(function execute(inputs, outputs) {

    var arrUserResponsible = [];
    var arrGroupApprover = [];

    var arrApproval = JSON.parse(inputs.record_case.variables.approval_configuration_j_j);
    arrApproval.forEach(function(apprConfig){
        arrUserResponsible.push(apprConfig.u_responsible_for_approval);
        arrGroupApprover.push(apprConfig.u_approval_group);
    });

    outputs.count = +arrGroupApprover.length;

    var userRecords = new GlideRecord('sys_user');
    userRecords.addEncodedQuery('sys_idIN' + arrUserResponsible.join(','));
    userRecords.query();

    outputs.users = userRecords;
    var countUser = 1;

    while(userRecords.next()){
        outputs['user' + countUser] = userRecords.getUniqueValue();
        countUser++;
    }

    

    var groupRecords = new GlideRecord('sys_user_group');
    groupRecords.addEncodedQuery('sys_idIN' + arrGroupApprover.join(','));
    groupRecords.query();

    outputs.groups =  groupRecords;
    var countGroup = 1;

    while(groupRecords.next()){
        outputs['group' + countGroup] = groupRecords.getUniqueValue();
        countGroup++;
    }    

})(inputs, outputs);

